function ClarkN_Lab8(g, s_a, h, n)

N = length(g);
slopes = zeros(4, N);

% Begin with RK4 for three time steps
for iter = 1:2
    state = s_a(iter, :);
    for c = 1:N
        slopes(1, c) = g{c}(state);
    end

    state = s_a(iter, :) + (h / 2) * [1, slopes(1, :)];
    for c = 1:N
        slopes(2, c) = g{c}(state);
    end

    state = s_a(iter, :) + (h / 2) * [1, slopes(2, :)];
    for c = 1:N
        slopes(3, c) = g{c}(state);
    end

    state = s_a(iter, :) + h * [1, slopes(3, :)];
    for c = 1:N
        slopes(4, c) = g{c}(state);
    end

    RK = (slopes(1, :) + 2 * slopes(2, :) + 2 * slopes(3, :) + slopes(4, :)) / 6;
    s_a(iter + 1, :) = s_a(iter, :) + h * [1, RK];
end

% Continue with the ABM3 algorithm
for steps = 3:n
    % Predictor
    P = s_a(steps, :) + h * (23 / 12 * slopes(1, :) - 4 / 3 * slopes(2, :) + 5 / 12 * slopes(3, :));
    P_slope = zeros(1, N);

    for c = 1:N
        P_slope = g{c};
    end

    % Corrector: Iterate until convergence
    while true
        C = s_a(steps, :) + h * (5 / 12 * slopes(1, :) + 2 / 3 * P_slope - 1 / 12 * slopes(2, :));
        C_slope = zeros(1, N);

        for c = 1:N
            C_slope = g{c};
        end

        % Check for convergence
        if max(abs(C_slope - P_slope)) < 1e-8
            break;
        end

        P = C;
        P_slope = C_slope;
    end

    % Update state values, slopes, and plots
    s_a(steps + 1, :) = C;
    slopes(1:3, :) = slopes(2:4, :);
    slopes(4, :) = C_slope;

    for c = 1:N
        subplot(N, 1, c)
        plot(s_a(1:steps + 1, 1), s_a(1:steps + 1, c + 1), 'b')
        ylabel(sprintf('Var%d', c))
        drawnow
    end
end

% Output final state
fprintf('Final state values (including time):\n');
disp(s_a(end, :));

end

